    /** Datapack enchantments must be looked up as holders at generation time. */
    private static Holder<Enchantment> ench(HolderLookup.Provider registries, ResourceKey<Enchantment> key) {
        return registries.lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(key);
    }

