    private AdvancementHolder orList(HolderLookup.Provider registries, Consumer<AdvancementHolder> consumer, ExistingFileHelper fileHelper, AdvancementHolder parent, ItemLike displayItem, String text, List<ItemLike> itemList) {
        Advancement.Builder temp = Advancement.Builder.advancement().parent(parent).display(displayItem, Component.translatable("rankine.advancements.story."+text+".title"), Component.translatable("rankine.advancements.story."+text+".description"),null,  AdvancementType.TASK, true, true, false);
        for (ItemLike item : itemList) {
            temp.addCriterion(RankineDataUtils.rl(item.asItem()).getPath(), InventoryChangeTrigger.TriggerInstance.hasItems(item));
        }
        return temp.requirements(AdvancementRequirements.Strategy.OR).save(consumer, ResourceLocation.parse("rankine:story/"+text), fileHelper);
    }
    private AdvancementHolder andList(HolderLookup.Provider registries, Consumer<AdvancementHolder> consumer, ExistingFileHelper fileHelper, AdvancementHolder parent, ItemLike displayItem, String text, List<ItemLike> itemList) {
        Advancement.Builder temp = Advancement.Builder.advancement().parent(parent).display(displayItem, Component.translatable("rankine.advancements.story."+text+".title"), Component.translatable("rankine.advancements.story."+text+".description"),null,  AdvancementType.TASK, true, true, false);
        for (ItemLike item : itemList) {
            temp.addCriterion(RankineDataUtils.rl(item.asItem()).getPath(), InventoryChangeTrigger.TriggerInstance.hasItems(item));
        }
        return temp.requirements(AdvancementRequirements.Strategy.AND).save(consumer, ResourceLocation.parse("rankine:story/"+text), fileHelper);
    }
    private AdvancementHolder andListChallenge(HolderLookup.Provider registries, Consumer<AdvancementHolder> consumer, ExistingFileHelper fileHelper, AdvancementHolder parent, ItemLike displayItem, String text, int XP, List<ItemLike> itemList) {
        Advancement.Builder temp = Advancement.Builder.advancement().parent(parent).display(displayItem, Component.translatable("rankine.advancements.challenges."+text+".title"), Component.translatable("rankine.advancements.challenges."+text+".description"),null,  AdvancementType.CHALLENGE, true, true, false);
        for (ItemLike item : itemList) {
            temp.addCriterion(RankineDataUtils.rl(item.asItem()).getPath(), InventoryChangeTrigger.TriggerInstance.hasItems(item));
        }
        return temp.requirements(AdvancementRequirements.Strategy.AND).rewards(AdvancementRewards.Builder.experience(XP)).save(consumer, ResourceLocation.parse("rankine:challenges/"+text), fileHelper);
    }

